vRtrIfDHCPProxyAdminState = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 3, 19, 1, 28), TmnxAdminState().clone('outOfService')).setMaxAccess("readcreate")
