vRtrInetStaticRouteCpeDropCnt = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 3, 24, 1, 23), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(1, 255)).clone(3)).setMaxAccess("readcreate")
