vRtrInetStaticRouteCommunityVal = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 3, 24, 1, 31), DisplayString().subtype(subtypeSpec=ValueSizeConstraint(0, 72)).clone(hexValue="")).setMaxAccess("readcreate")
