vRtrIfDcpStaticHoldDownEnd = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 3, 0, 51)).setObjects(("TIMETRA-VRTR-MIB", "vRtrIfDcpFpStaticExcdCountHi"), ("TIMETRA-VRTR-MIB", "vRtrIfDcpFpStaticExcdCountLo"), ("TIMETRA-VRTR-MIB", "vRtrIfDCpuProtPolicy"), ("TIMETRA-VRTR-MIB", "vRtrIfDcpTimeEventOccured"))
