tmnxVRtrNgBfdSessDeleted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 3, 0, 71)).setObjects(("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtLclDisc"), ("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtOperFlags"), ("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtLspPathId"), ("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtLspPathTunnelId"), ("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtSvcId"), ("TIMETRA-VRTR-MIB", "vRtrIfBfdSessExtSdpBindId"))
